quickstart.code:
from zodify import validate

schema = {"name": str, "age": int}
assert validate(schema, {"name": "Ada", "age": 36}) == {"name": "Ada", "age": 36}
try:
    validate(schema, {"name": "Ada", "age": "36"})
except ValueError:
    pass  # String input is rejected by default.
else:
    raise AssertionError("Expected validation failure")
print("quickstart: passed")

schemas.code:
from zodify import validate

schema = {"users": [{"name": str}], "enabled": bool}
assert validate(schema, {"users": [{"name": "Ada"}], "enabled": True})["users"][0]["name"] == "Ada"
# A predicate accepts the original value when it returns a truthy result.
assert validate({"port": lambda x: type(x) is int and 1 <= x <= 65535}, {"port": 8080}) == {"port": 8080}
print("schemas: passed")

exact-types.code:
import json
from zodify import validate

accepted = []
for token in ["1", "1.0", "true", '"1"']:
    value = json.loads(token)
    try:
        validate({"count": int}, {"count": value})
    except ValueError:
        accepted.append(False)
    else:
        accepted.append(True)
assert accepted == [True, False, False, False]
assert validate({"port": int}, {"port": "8080"}, coerce=True) == {"port": 8080}
assert validate({"value": int | str}, {"value": "1"}, coerce=True)["value"] == 1
assert validate({"value": str | int}, {"value": "1"}, coerce=True)["value"] == "1"
print("exact-types: passed")

optional-defaults.code:
from zodify import Optional, validate

assert validate({"name": Optional(str)}, {}) == {}
assert validate({"name": str | None}, {"name": None}) == {"name": None}
assert validate({"name": Optional(str, "Ada")}, {}) == {"name": "Ada"}
# Released 0.8.0 defaults are inserted as supplied, without validation or copying.
default = []
result = validate({"items": Optional([str], default)}, {})
assert result["items"] is default
assert validate({"count": Optional(int, "unchecked")}, {})["count"] == "unchecked"
try:
    validate({"name": str | None}, {})
except ValueError:
    pass  # Nullable still requires the key.
else:
    raise AssertionError("Expected missing-key failure")
print("optional-defaults: passed")

errors.code:
from zodify import ValidationError, validate

try:
    validate({"port": int}, {"port": "wrong"}, error_mode="structured")
except ValidationError as error:
    assert error.issues[0]["path"] == "port"
    assert error.issues[0]["expected"] == "int"
else:
    raise AssertionError("Expected structured failure")
print("errors: passed")

config-validation.code:
from zodify import Optional, validate

schema = {"host": str, "port": int, "debug": Optional(bool, False)}
config = {"host": "localhost", "port": 8080}
assert validate(schema, config)["debug"] is False
with_typo = dict(config, debgu=True)
try:
    validate(schema, with_typo)
except ValueError:
    pass  # Reject unknown keys: catch misspelled configuration.
else:
    raise AssertionError("Expected unknown-key failure")
clean = validate(schema, with_typo, unknown_keys="strip")
assert "debgu" not in clean  # Explicitly drops data; does not repair the typo.
assert "debgu" in with_typo  # Original input is unchanged here.
print("config-validation: passed")

cli-input-validation.code:
import argparse
from zodify import validate

parser = argparse.ArgumentParser()
parser.add_argument("--port", required=True)
parser.add_argument("--debug", default="false")
schema = {"port": int, "debug": bool}
args = vars(parser.parse_args(["--port", "8080", "--debug", "yes"]))
assert validate(schema, args, coerce=True) == {"port": 8080, "debug": True}
try:
    validate(schema, {"port": "not-a-port", "debug": "false"}, coerce=True)
except ValueError:
    pass
else:
    raise AssertionError("Expected conversion failure")
print("cli-input-validation: passed")

json-object-validation.code:
import json
from zodify import validate

def read_user(text):
    data = json.loads(text)
    if type(data) is not dict:
        raise ValueError("Expected a JSON object")
    return validate({"name": str, "age": int}, data)

assert read_user('{"name":"Ada","age":36}')["age"] == 36
for invalid in ['[]', '{"name":"Ada","age":"36"}', '{"name":']:
    try:
        read_user(invalid)
    except ValueError:  # Includes JSONDecodeError.
        pass
    else:
        raise AssertionError("Expected parsing or validation failure")
print("json-object-validation: passed")

